import { Hono } from './hono'
import { setCookie } from './helper/cookie'

describe('tmp scenario', () => {
  it('middleware setCookie + handler returns Response with Set-Cookie', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      setCookie(c, 'middleware', '1', { path: '/' })
      await next()
    })
    app.get('/', () => {
      return new Response('ok', {
        headers: { 'set-cookie': 'handler=2; Path=/' },
      })
    })
    const res = await app.request('/')
    console.log('SCENARIO A', res.headers.getSetCookie())
  })

  it('middleware touches c.res + handler returns Response with Set-Cookie', async () => {
    const app = new Hono()
    app.use('*', async (c, next) => {
      c.res.headers.append('set-cookie', 'middleware=1; Path=/')
      await next()
    })
    app.get('/', () => {
      return new Response('ok', {
        headers: { 'set-cookie': 'handler=2; Path=/' },
      })
    })
    const res = await app.request('/')
    console.log('SCENARIO B', res.headers.getSetCookie())
  })
})

